// === ⚙️ CONFIGURATION ===
// Set these 3 IDs for each node instance
const PHASE_ID = items[0].json.PHASE_ID;
const AGENT_ID = items[0].json.AGENT_ID;
const TASK_ID = items[0].json.TASK_ID;

// Standard Setup
const INPUT_DATA = items[0].json;  // output of previous node
const CONFIG = INPUT_DATA.config;
const fullHistory = INPUT_DATA.history || [];

// Replaces ${VAR.PATH} placeholders with real values from the context object
// Supports: ${Node Name:variable} OR ${variable} (from localContext)
function resolveTemplate(templateStr) {
    if (typeof templateStr !== 'string') return templateStr;

    return templateStr.replace(/\$\{([^}]+)\}/g, (match, path) => {
        // 1. DEFAULT: Start with the global items[0].json
        // We can access 'items' directly because it is in the scope
        let value = items[0].json; 

        // 2. OPTIONAL: Handle Node Syntax (NodeName:variable)
        // If the path has a colon, we switch 'value' to look at that specific node
        if (path.includes(':')) {
            const [nodeName, varPath] = path.split(/:(.+)/);
            // We can access '$' directly because it is in the scope
            try {
                value = $(nodeName).first().json;
                path = varPath; // Update path to be just the variable part
            } catch (e) {
                throw new Error(`Node '${nodeName}' not found.`);
            }
        }

        // 3. Drill down into 'value'
        const keys = path.trim().split('.');
        for (const key of keys) {
            if (value === undefined || value === null) {
                 throw new Error(`MISSING: Path '${path}' not found.`);
            }
            value = value[key];
        }

        if (typeof value === 'object') return JSON.stringify(value, null, 2);
        return String(value);
    });
}

// === 🧭 NAVIGATE CONFIG ===
if (!CONFIG || !CONFIG.phases) throw new Error("Missing 'config'. Ensure Load Config runs first.");

const phaseConfig = CONFIG.phases[PHASE_ID];
if (!phaseConfig) throw new Error(`Phase ${PHASE_ID} not found in config.`);

const agentConfig = phaseConfig.agents[AGENT_ID];
if (!agentConfig) throw new Error(`Agent ${AGENT_ID} not found in Phase ${PHASE_ID}.`);

const taskConfig = agentConfig.tasks[TASK_ID];
if (!taskConfig) throw new Error(`Task ${TASK_ID} not found in Agent ${AGENT_ID}.`);

// === 🧠 ASSEMBLE IDENTITY (System Instruction) ===
const systemParts = [
  CONFIG.global_task_explanation,
  phaseConfig.identity,
  agentConfig.identity
].filter(Boolean);

const finalSystemInstruction = resolveTemplate(systemParts.join("\n\n"));

// === 📜 ASSEMBLE HISTORY ===
let scopedHistory = [];
const scope = taskConfig.history_scope || "agent";

if (scope === "global") scopedHistory = fullHistory;
else if (scope === "phase") scopedHistory = fullHistory.filter(h => h.phase_id === PHASE_ID);
else if (scope === "agent") scopedHistory = fullHistory.filter(h => h.phase_id === PHASE_ID && h.agent_id === AGENT_ID); 
// If scope is "none", scopedHistory remains []

// === 📝 CONSTRUCT USER PROMPT ===
// Priority: Task > Agent > Phase > Config Default > Error
let rawGlobalContext = taskConfig.context_override || 
                       agentConfig.context_override || 
                       phaseConfig.context_override || 
                       CONFIG.default_context_template;

if (!rawGlobalContext) {
    throw new Error("CONTEXT ERROR: No context_override found in Task/Agent/Phase and no 'default_context_template' found in Config.");
}

const globalContext = resolveTemplate(rawGlobalContext);

let historySection = scopedHistory.length > 0 ? `=== HISTORY ===\n${JSON.stringify(scopedHistory, null, 2)}` : "";

const userPrompt = `
=== CONTEXT ===
${globalContext}

${historySection}

=== YOUR CURRENT TASK ===
${resolveTemplate(taskConfig.instruction)}
`.trim();

// === 🖼️ IMAGE HANDLING ===
let parts = [{ text: userPrompt }];

if (taskConfig.view_image === true) {
    let imgData = null;
    let imgMime = null;

    // 1. Try fetching from explicit source (Configured Override)
    if (taskConfig.image_source) {
        try {
            const sourceItem = $(taskConfig.image_source).last().json;
            imgData = sourceItem.base64_img_string;
            imgMime = sourceItem.base64_img_string_mime;
        } catch (e) {
            throw new Error(`IMAGE ERROR: 'image_source' was set to '${taskConfig.image_source}', but that node execution could not be found.`);
        }
    } 
    // 2. Fallback: Try fetching from immediate input
    else {
        imgData = INPUT_DATA.base64_img_string;
        imgMime = INPUT_DATA.base64_img_string_mime;
    }

    // 3. VALIDATION: Fail if blind
    if (!imgData || !imgMime) {
        throw new Error(`CONFIGURATION ERROR: Agent '${AGENT_ID}' (Task: '${TASK_ID}') requires 'view_image: true', but no 'base64_img_string' was found in input context or specified 'image_source'.`);
    }

    // 4. Attach Image
    parts.push({
        inline_data: {
            mime_type: imgMime,
            data: imgData
        }
    });
}

// === 🎯 MODEL SELECTION ===
// Logic: Task Specific > Agent Specific > Global Default
const model_url = taskConfig.model_url || agentConfig.model_url || CONFIG.default_model_url;
const outputType = taskConfig.output_type || "json";

// Output containers
let aiResult;
let finalImageBase64 = null;
let requestBody = {};

// === ⚡ CHECK FOR NO_MODEL MODE ===
if (model_url === "no_model") {
    const rawResult = taskConfig.result;
    if (rawResult === undefined) {
        throw new Error(`CONFIGURATION ERROR: Agent '${AGENT_ID}' (Task: '${TASK_ID}') has 'model_url':'no_model' but is missing 'result'.`);
    }

    const resolvedResult = resolveTemplate(rawResult);

    // Try to auto-parse JSON if it looks like one
    if (typeof resolvedResult === 'string' && (resolvedResult.trim().startsWith('{') || resolvedResult.trim().startsWith('['))) {
        try {
            aiResult = JSON.parse(resolvedResult);
        } catch (e) {
            aiResult = resolvedResult;
        }
    } else {
        aiResult = resolvedResult;
    }

    requestBody = { mode: "no_model", result_template: rawResult };

} else {
    // === 🚀 CONSTRUCT REQUEST (STANDARD) ===
    requestBody = {
        contents: [{ parts: parts }],
        systemInstruction: { parts: [{ text: finalSystemInstruction }] }
    };

    if (outputType === "json") {  // constrained generation - json schema
        requestBody.generationConfig = {
            response_mime_type: "application/json",
            response_schema: taskConfig.schema
        };
    } else {
        requestBody.generationConfig = {};
    }

    // === 📡 SEND REQUEST ===
    let response;
    const MAX_RETRIES = 3;

    for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        try {
            const options = {
                method: 'POST',
                url: model_url,
                qs: { key: CONFIG.api_key },
                headers: { 'Content-Type': 'application/json' },
                body: requestBody,  // "json: true" causes auto stringify request
                json: true // and parse the response JSON into a JS object
            };

            // Note: Gemini returns images as base64 strings inside JSON.
            response = await this.helpers.httpRequest(options);
            break; // Success

        } catch (error) {
            const status = error.response?.status;
            const apiMsg = error.response?.data?.error?.message || error.message;
            // STOP IF ERROR IS PERMANENT (400 Bad Request, 401 Unauthorized, etc.), We only retry on 429 (Rate Limit) or 5xx (Server Errors)
            if (status && status < 500 && status !== 429) {
                throw new Error(`Gemini API Error ${status} (Non-Retriable): ${apiMsg}`);
            }
            if (attempt === MAX_RETRIES) throw new Error(`Agent failed after ${MAX_RETRIES} attempts. Last Error: ${apiMsg}`);
            await new Promise(r => setTimeout(r, attempt * 2000));
        }
    }

    // === 📦 PARSE RESPONSE ===
    if (outputType === "image_blob") {
        const content = typeof response === 'string' ? JSON.parse(response) : response;  // Extract Image Response from JSON
        const part = content.candidates?.[0]?.content?.parts?.[0];  // Locate the inline data in the standard Gemini response structure

        const inlineData = part?.inlineData;  // camelCase in raw JSON responses
        if (inlineData?.data) {
            finalImageBase64 = inlineData.data;
            aiResult = { status: "success", message: "Image generated successfully" };
        } else {  // Fallback: Check snake_case for robustness
            const inline_data = part?.inline_data;
            if (inline_data?.data) {
                finalImageBase64 = inline_data.data;
                aiResult = { status: "success", message: "Image generated successfully" };
            } else {  // Model might have refused or returned text
                let rawDump = part?.text || JSON.stringify(content);
                if (rawDump.length > 500) rawDump = rawDump.substring(0, 500) + "...";
                aiResult = { 
                    status: "error", 
                    message: "No image found in response", 
                    raw_text: rawDump
                };
            }
        }
    } else {
        // Standard JSON Response
        const content = typeof response === 'string' ? JSON.parse(response) : response;
        if (content.candidates && content.candidates[0]) {
            const rawText = content.candidates[0].content.parts[0].text;
            // Sometimes the model returns markdown code blocks ```json ... ```
            const cleanText = rawText.replace(/```json\n?|\n?```/g, "");
            aiResult = JSON.parse(cleanText);
        } else {
            aiResult = content;
        }
    }
}

// === 📤 CONSTRUCT OUTPUT ===
// Query/response record to append to history
const stepRecord = {
  phase_id: PHASE_ID,
  agent_id: AGENT_ID,
  task_id: TASK_ID,
  task_instruction: taskConfig.instruction,
  output: aiResult
};

// Helper for Smart Truncation (Debug Logs)
function sanitize(key, value) {
    if (typeof value === "string" && value.length > 100) {
        if (key === "data" && (this.mimeType || this.mime_type)) return "<IMAGE_BLOB(Gemini)>";
        if (key === "base64_img_string") return "<IMAGE_BLOB>";
        if (key === "thoughtSignature") return "<THOUGHT_SIGNATURE>";
    }
    return value;
}

const outputData = {
    // 1. Debug Info
    debug_query: taskConfig.instruction,
    debug_response: JSON.parse(JSON.stringify(aiResult, sanitize)),
    debug_full_request_body: JSON.parse(JSON.stringify(requestBody, sanitize)),

    // 2. Parsed AI Response Fields
    // If aiResult is an object (standard JSON), we spread it so properties (reasoning, python_code, etc.) are top-level.
    ...(typeof aiResult === 'object' ? aiResult : { raw_response: aiResult }),

    // 3. Image Data (If present)
    ...(finalImageBase64 ? { base64_img_string: finalImageBase64, base64_img_string_mime: "image/png" } : {}),

    // 4. Context Preservation (Optional - Keep description alive if not updated)
    ...((INPUT_DATA.latest_description && (!aiResult || !aiResult.latest_description)) 
        ? { latest_description: INPUT_DATA.latest_description } 
        : {}),

    // 5. History & Config
    history: [...fullHistory, stepRecord],
    config: CONFIG
};

// === 📡 GUI PROGRESS BROADCAST (Fire & Forget) ===
if (CONFIG.enable_gui_logging === true && CONFIG.gui_webhook_url) {
    try {
        const guiPayload = {
            phase_id: PHASE_ID,
            agent_id: AGENT_ID,
            task_id: TASK_ID,
            query: outputData.debug_query,
            response: outputData.debug_response, // Already sanitized
            timestamp: new Date().toISOString()
        };

        // We await it so n8n doesn't terminate the promise context prematurely,
        // but the strict timeout prevents it from holding up the workflow.
        await this.helpers.httpRequest({
            method: 'POST',
            url: CONFIG.gui_webhook_url,
            headers: { 'Content-Type': 'application/json' },
            body: guiPayload,
            json: true,
            timeout: 500 // 0.5 seconds max - don't hang if GUI is slow/down
        });
    } catch (e) {
        // Silently swallow the error. We don't care if the web app is unreachable.
        // Uncomment the line below if you want to see the failure in your n8n server logs:
        // console.log(`GUI Broadcast failed for ${AGENT_ID}:`, e.message);
    }
}

return [{ json: outputData }];

