    ...(typeof aiResult === 'object' ? aiResult : { raw_response: aiResult }),

    // 3. Image Data (If present)
    ...(finalImageBase64 ? { base64_img_string: finalImageBase64, base64_img_string_mime: "image/jpg" } : {}),

